    content = f.read()

lines = content.split('\n')

def decode_ssh_result_any(line):
    """Try all decoding paths"""
    try:
        outer = json.loads(line)
        msg = outer.get('message', {})
        if msg.get('role') != 'user':
            return None, None
        content_list = msg.get('content', [])
        if not content_list:
            return None, None

        for item in content_list:
            if item.get('type') == 'tool_result':
                c = item.get('content', '')
                if not c or not isinstance(c, str):
                    continue

                # Try direct nested JSON decode (ssh result format)
                try:
                    l1 = json.loads(c)
                    if 'result' in l1:
                        l2 = json.loads(l1['result'])
                        if l2.get('success'):
                            return l2['data'].get('stdout', ''), None
                    elif 'type' in l1 and l1.get('type') == 'user':
                        # Embedded JSONL
                        for inner_item in l1['message']['content']:
                            if inner_item.get('type') == 'tool_result':
                                inner_c = inner_item.get('content', '')
                                inner_l1 = json.loads(inner_c)
                                inner_l2 = json.loads(inner_l1['result'])
                                if inner_l2.get('success'):
                                    return inner_l2['data'].get('stdout', ''), None
                except:
                    pass
        return None, None
    except:
        return None, None

# Find all large successful SSH results in lines 400-1074
large_results = []
for i in range(400, len(lines)):
    stdout, err = decode_ssh_result_any(lines[i])
    if stdout and len(stdout) > 500 and 'per_task_R2' in stdout:
        trunc = '截断' in stdout
        large_results.append((i, len(stdout), trunc, stdout[:300]))

print(f"Found {len(large_results)} large results with per_task_R2:")
for i, size, trunc, preview in large_results:
    print(f"  Line {i}: len={size}, truncated={trunc}")
    print(f"  Preview: {preview[:200]}")
    print()
